import pandas as pd
from sklearn.preprocessing import StandardScaler
from sklearn.decomposition import PCA
from sklearn.cluster import DBSCAN
import numpy as np

def main():
    print("--- Starting Unsupervised Degradation Monitoring (PCA + DBSCAN) ---")
    
    # 1. Load Data generated by the supervised model
    data_path = '../data/telemetry_with_predictions.csv'
    try:
        df = pd.read_csv(data_path)
        print(f"Loaded {len(df)} rows from {data_path}")
    except FileNotFoundError:
        print(f"Error: Could not find {data_path}. Ensure you run supervised_xgboost.py first.")
        return

    # 2. Filter for Daylight Hours
    # It doesn't make sense to detect degradation when the sun isn't shining (irradiance == 0)
    daylight_df = df[df['solar_irradiance_w_m2'] > 10].copy()
    print(f"Filtered to {len(daylight_df)} daylight rows for anomaly detection.")

    # 3. Feature Engineering for Unsupervised Pipeline
    # We want to find clusters of states based on the weather and our efficiency residual
    features_for_clustering = ['solar_irradiance_w_m2', 'module_temp_c', 'efficiency_residual']
    X = daylight_df[features_for_clustering]

    # Standardize the features (Crucial for PCA and DBSCAN)
    scaler = StandardScaler()
    X_scaled = scaler.fit_transform(X)

    # 4. Dimensionality Reduction (PCA)
    # Reduces noise and helps DBSCAN find better density regions
    pca = PCA(n_components=2)
    X_pca = pca.fit_transform(X_scaled)
    print(f"PCA Variance Explained: {pca.explained_variance_ratio_}")

    # 5. Anomaly Detection (DBSCAN)
    # eps (radius) and min_samples dictate how dense a cluster must be
    dbscan = DBSCAN(eps=0.6, min_samples=10)
    daylight_df['cluster_label'] = dbscan.fit_predict(X_pca)

    # DBSCAN labels anomalies as -1
    anomalies = daylight_df[daylight_df['cluster_label'] == -1]
    
    # We are specifically interested in "Underperforming" Anomalies (Degradation)
    # meaning the actual yield was significantly lower than the XGBoost expected yield
    degradation_flags = anomalies[anomalies['efficiency_residual'] < -0.5] # threshold configurable
    
    # 6. Results Summary
    total_points = len(daylight_df)
    total_anomalies = len(anomalies)
    degraded_points = len(degradation_flags)
    
    print("\n--- Degradation Analysis Results ---")
    print(f"Total Operational Datapoints: {total_points}")
    print(f"Total Statistical Anomalies: {total_anomalies} ({(total_anomalies/total_points)*100:.2f}%)")
    print(f"Severe Underperformance (Degradation) Flags: {degraded_points}")
    
    if degraded_points > 0:
        print("\n[ALERT] Potential degradation or severe soiling detected in the following recent periods:")
        # Sort by most negative residual (worst underperformance)
        worst_offenders = degradation_flags.sort_values(by='efficiency_residual').head(5)
        for _, row in worst_offenders.iterrows():
            print(f" - Time: {row['timestamp']} | Expected: {row['expected_yield_kwh']:.2f} | Actual: {row['energy_yield_kwh']:.2f} | Deficit: {row['efficiency_residual']:.2f} kWh")
    else:
        print("\n[SUCCESS] Panels are operating optimally. No significant degradation detected.")
        
    # Save anomalies
    output_path = '../data/detected_anomalies.csv'
    degradation_flags.to_csv(output_path, index=False)
    print(f"\nSaved degradation alerts to {output_path}")

if __name__ == "__main__":
    main()
